// Command abigen generates, from the layouts table in table.go, the constants that the runtime and the compilers share:
// the offsets and sizes of the string, array, byte array and union boxes. `go generate ./internal/abigen` runs it in
// that directory.
package main

//go:generate go run .

import (
	"fmt"
	"go/format"
	"os"
	"strconv"
	"strings"
)

const header = "Code generated by internal/abigen from internal/abigen/table.go; DO NOT EDIT."

// output is one generated file.
type output struct {
	path string
	to   dest
	gen  func(rows []layoutConst) string
}

var outputs = []output{
	{"../../runtime/layout_gen.maxon", toRuntime, func(r []layoutConst) string { return maxonFile(r, false, true) }},
	{"../../self/ir/layout_gen.maxon", toSelfIR, func(r []layoutConst) string { return maxonFile(r, true, true) }},
	{"../../self/backend/layout_gen.maxon", toSelfBack, func(r []layoutConst) string { return maxonFile(r, true, false) }},
	{"../ir/layout_gen.go", toGoIR, func(r []layoutConst) string { return goFile(r, "ir", true) }},
	{"../backend/layout_gen.go", toGoBackend, func(r []layoutConst) string { return goFile(r, "backend", false) }},
}

func main() {
	for _, o := range outputs {
		if err := os.WriteFile(o.path, []byte(generate(o)), 0o644); err != nil {
			fmt.Fprintln(os.Stderr, "abigen:", err)
			os.Exit(1)
		}
	}
}

// generate is the text of one output file.
func generate(o output) string {
	var rows []layoutConst
	for _, c := range layouts {
		if c.to&o.to != 0 {
			rows = append(rows, c)
		}
	}
	return o.gen(rows)
}

// bytes is the value of a row in bytes.
func (c layoutConst) bytes() int {
	if c.plain {
		return c.value
	}
	return c.value * wordSize
}

// maxonFile is a Maxon file of the rows. A name is exported for another module to use, and typed as a Count where the
// code that reads it does arithmetic on addresses, and left as a plain literal where it is a displacement.
func maxonFile(rows []layoutConst, export, count bool) string {
	var b strings.Builder
	b.WriteString("// " + header + "\n")
	for _, c := range rows {
		b.WriteString("\n// " + c.name + " is " + c.doc + "\n")
		if export {
			b.WriteString("export ")
		}
		b.WriteString("let " + c.name + " = " + strconv.Itoa(c.bytes()))
		if count {
			b.WriteString(" as Count")
		}
		b.WriteString("\n")
	}
	return b.String()
}

// goFile is a Go file of the rows, whose names are exported when the package's own code is not the only reader. A row
// that is a count of words is written as the multiple of wordBytes it is.
func goFile(rows []layoutConst, pkg string, export bool) string {
	var b strings.Builder
	b.WriteString("// " + header + "\n\npackage " + pkg + "\n\nconst (")
	for _, c := range rows {
		name := c.name
		if export {
			name = strings.ToUpper(name[:1]) + name[1:]
		}
		b.WriteString("\n\t// " + name + " is " + c.doc + "\n\t" + name + " = " + goValue(c, export) + "\n")
	}
	b.WriteString(")\n")
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		panic(err)
	}
	return string(src)
}

func goValue(c layoutConst, export bool) string {
	if c.plain {
		return strconv.Itoa(c.value)
	}
	word := wordBytesName
	if export {
		word = "WordBytes"
	}
	switch c.value {
	case 0:
		return "0"
	case 1:
		return word
	}
	return strconv.Itoa(c.value) + " * " + word
}
